const r = $json || {};
const t = r.tenant || {};
return [{ json: {
  ok: r.ok === true,
  tenant_id: t.id || null, tag: t.tag || null, kind: t.kind || null, via: t.via || null,
  caller_env: (r.caller || {}).env || null,
  keys: (r.keys || []).map((k) => ({ prefix: k.prefix, env: k.env, revoked: Boolean(k.revoked) })),
  next_step: r.next_step ? { id: r.next_step.id, title: r.next_step.title } : null,
} }];
